Rules.InvariantScript:
With(
    {
        varColParentAccounts: Filter(
            'CAPEX Account Lists',
            And(
                Or(
                    IsBlank('Parent Account'),
                    'Parent Account'.Number = "10005"
                ),
                Not(Number = "10005")
            )
        )
    },
    Table(
        {
            ItemKey: "orderAccounts",
            ItemDisplayName: "Reorder",
            ItemIconName: "NumberedList",
            ItemEnabled: And(
                CountIf(
                    varColParentAccounts,
                    true
                ) > 1,
                DataSourceInfo(
                    'CAPEX Account Lists',
                    DataSourceInfo.EditPermission
                )
            )
        },
        {
            ItemKey: "newAccount",
            ItemDisplayName: "New",
            ItemIconName: "Add",
            ItemEnabled: DataSourceInfo(
                'CAPEX Account Lists',
                DataSourceInfo.CreatePermission
            )
        },
        {
            ItemKey: "editAccount",
            ItemDisplayName: "Edit",
            ItemIconName: "Edit",
            ItemEnabled: And(
                Not(IsBlank(locSelectedAccount)),
                RecordInfo(
                    locSelectedAccount,
                    RecordInfo.EditPermission
                )
            )
        },
        {
            ItemKey: "activateAccount",
            ItemDisplayName: "Activate",
            ItemIconName: "ActivateOrders",
            ItemVisible: And(
                Not(IsBlank(locSelectedAccount)),
                Not(locSelectedAccount.Status = 'Status (CAPEX Account Lists)'.Active)
            ),
            ItemEnabled: RecordInfo(
                locSelectedAccount,
                RecordInfo.EditPermission
            )
        },
        {
            ItemKey: "deactivateAccount",
            ItemDisplayName: "Deactivate",
            ItemIconName: "DeactivateOrders",
            ItemVisible: And(
                Not(IsBlank(locSelectedAccount)),
                locSelectedAccount.Status = 'Status (CAPEX Account Lists)'.Active
            ),
            ItemEnabled: RecordInfo(
                locSelectedAccount,
                RecordInfo.EditPermission
            )
        },
        {
            ItemKey: "deleteAccount",
            ItemDisplayName: "Delete",
            ItemIconName: "Delete",
            ItemVisible: And(
                Not(IsBlank(locSelectedAccount)),
                And(
                    IsBlank(
                      LookUp(
                            'CAPEX Project Contracts',
                            Account.'CAPEX Account List' in  Filter('CAPEX Account Lists','Parent Account'.'CAPEX Account List'= locSelectedAccount.'CAPEX Account List').'CAPEX Account List'
                        )
                    ),
                    IsEmpty(
                        Filter(
                            colCapexAccounts,
                            'Parent Account'.'CAPEX Account List' = locSelectedAccount.'CAPEX Account List'
                        ).'CAPEX Account List'
                    )
                )
            ),
            ItemEnabled: RecordInfo(
                locSelectedAccount,
                RecordInfo.DeletePermission
            )
        }
    )
)

